const fs = require('node:fs');
const cp = require('node:child_process');
const ts = require('typescript');
const files = cp.execFileSync('git', ['ls-files'], { encoding: 'utf8' }).trim().split(/\r?\n/).filter(p => /\.(test|spec)\.[cm]?[jt]sx?$/.test(p) && !p.includes('/integration/'));
const printer = ts.createPrinter({ removeComments: true });
const cases = [];
const summaries = [];
for (const path of files) {
  const source = fs.readFileSync(path, 'utf8');
  const tree = ts.createSourceFile(path, source, ts.ScriptTarget.Latest, true);
  const tests = [];
  function visit(node, scopes) {
    if (ts.isCallExpression(node)) {
      const expression = node.expression.getText(tree);
      if (/^(describe|suite)(\.|$)/.test(expression)) scopes = [...scopes, node.arguments[0]?.getText(tree)];
      if (/^(it|test)(\.|\(|$)/.test(expression)) {
        const body = node.arguments.find(a => ts.isArrowFunction(a) || ts.isFunctionExpression(a));
        if (body) {
          const assertions = [];
          function collect(n) {
            if (ts.isExpressionStatement(n) && /\b(expect|assert)\b/.test(n.getText(tree))) assertions.push(n.getText(tree).replace(/\s+/g, ' '));
            ts.forEachChild(n, collect);
          }
          collect(body.body);
          const c = { path, line: tree.getLineAndCharacterOfPosition(node.getStart(tree)).line + 1, endLine: tree.getLineAndCharacterOfPosition(node.end).line + 1, name: node.arguments[0]?.getText(tree), scope: scopes.join(' > '), assertions, body: printer.printNode(ts.EmitHint.Unspecified, body, tree), source: node.getText(tree) };
          tests.push(c); cases.push(c);
        }
      }
    }
    ts.forEachChild(node, child => visit(child, scopes));
  }
  visit(tree, []);
  summaries.push({path, lines: source.split('\n').length, cases: tests.length});
}
fs.writeFileSync('local/unit-test-inventory.json', JSON.stringify({ files: summaries, cases }, null, 2));
const grouped = new Map();
for (const c of cases) { const key = c.path + c.scope + c.body; const list = grouped.get(key) || []; list.push(c); grouped.set(key, list); }
console.log(JSON.stringify({ files: files.length, cases: cases.length, lines: summaries.reduce((a,b) => a+b.lines,0), exactDuplicateBodies: [...grouped.values()].filter(x => x.length > 1).map(x => x.map(({path,line,name,scope}) => ({path,line,name,scope}))) }, null, 2));
for (const f of summaries) {
  console.log('\n' + f.path + ' (' + f.cases + ' cases)');
  for (const c of cases.filter(c=>c.path===f.path)) console.log(c.line + ': ' + c.scope + ' > ' + c.name);
}

