import { describe, expect, it } from "vitest";
import {
  areAutoCanvasRelationsSuppressed,
  shouldCreateAutoCanvasRelations,
  withAutoCanvasRelationsSuppressed,
} from "~/components/canvas/autoCanvasRelationsSuppression";

describe("auto canvas relation suppression", () => {
  it("suppresses auto canvas relations only inside the callback", () => {
    expect(areAutoCanvasRelationsSuppressed()).toBe(false);

    const value = withAutoCanvasRelationsSuppressed(() => {
      expect(areAutoCanvasRelationsSuppressed()).toBe(true);
      return "loaded";
    });

    expect(value).toBe("loaded");
    expect(areAutoCanvasRelationsSuppressed()).toBe(false);
  });

  it("keeps suppression active for nested callbacks", () => {
    withAutoCanvasRelationsSuppressed(() => {
      expect(areAutoCanvasRelationsSuppressed()).toBe(true);

      withAutoCanvasRelationsSuppressed(() => {
        expect(areAutoCanvasRelationsSuppressed()).toBe(true);
      });

      expect(areAutoCanvasRelationsSuppressed()).toBe(true);
    });

    expect(areAutoCanvasRelationsSuppressed()).toBe(false);
  });

  it("restores suppression state when the callback throws", () => {
    expect(() =>
      withAutoCanvasRelationsSuppressed(() => {
        throw new Error("load failed");
      }),
    ).toThrow("load failed");

    expect(areAutoCanvasRelationsSuppressed()).toBe(false);
  });

  it("allows auto canvas relations for user-created records", () => {
    expect(shouldCreateAutoCanvasRelations({ source: "user" })).toBe(true);
  });

  it("skips auto canvas relations for remote-created records", () => {
    expect(shouldCreateAutoCanvasRelations({ source: "remote" })).toBe(false);
  });

  it("skips user-created records while suppression is active", () => {
    withAutoCanvasRelationsSuppressed(() => {
      expect(shouldCreateAutoCanvasRelations({ source: "user" })).toBe(false);
    });
  });
});
import { describe, expect, it, vi } from "vitest";
import type { TreeNode } from "roamjs-components/types";

vi.mock("roamjs-components/queries/getFullTreeByParentUid", () => ({
  default: () => ({ children: [] }),
}));
vi.mock("roamjs-components/queries/getPageViewType", () => ({
  default: () => "bullet",
}));
vi.mock("~/utils/pageToMarkdown", () => ({
  toMarkdown: ({ c }: { c: TreeNode }) => `- ${c.text}`,
}));

// Runs before the imports below: getDiscourseNodes calls generateUID at module load.
vi.hoisted(() => {
  (globalThis as { window?: unknown }).window = {
    roamAlphaAPI: { util: { generateUID: () => "someUid" } },
  };
});

import { buildFullMarkdown } from "~/utils/roamToCrossAppConverters";

const block = (text: string): TreeNode =>
  ({ text, children: [], order: 0, uid: "" }) as unknown as TreeNode;

describe("buildFullMarkdown", () => {
  it("emits the body without the page title", () => {
    expect(
      buildFullMarkdown({ blocks: [block("first"), block("second")] }),
    ).toBe("- first\n- second\n");
  });

  it("emits an empty string for a page with no blocks", () => {
    expect(buildFullMarkdown({ blocks: [] })).toBe("");
  });

  it("ignores blocks that are empty and childless", () => {
    expect(buildFullMarkdown({ blocks: [block(""), block("kept")] })).toBe(
      "- kept\n",
    );
  });
});

describe("canvas node menu", () => {
  it("keeps a portaled mouse selection out of canvas pointer capture and refreshes after the write", async () => {
    let finishUpdate: () => void = () => {};
    updateBlock.mockImplementation(
      () =>
        new Promise<void>((resolve) => {
          finishUpdate = resolve;
        }),
    );
    const menuItem = document.querySelector<HTMLElement>(".bp3-menu-item");
    expect(menuItem).not.toBeNull();
    act(() => {
      menuItem!.dispatchEvent(new MouseEvent("pointerdown", { bubbles: true }));
      menuItem!.click();
    });
    expect(onCanvasPointerDown).not.toHaveBeenCalled();
    await act(async () => {
      await vi.advanceTimersByTimeAsync(100);
    });
    expect(updateBlock).toHaveBeenCalledExactlyOnceWith({
      uid: "block-uid",
      text: "A canvas block #claim",
    });
    expect(onTagAdded).not.toHaveBeenCalled();
    await act(async () => {
      finishUpdate();
      await Promise.resolve();
    });
    expect(onTagAdded).toHaveBeenCalledExactlyOnceWith("A canvas block #claim");
    expect(onClose).toHaveBeenCalled();
  });

  it("still selects tags using the keyboard", async () => {
    updateBlock.mockResolvedValue(undefined);
    act(() => {
      document.dispatchEvent(
        new KeyboardEvent("keydown", { key: "Enter", bubbles: true }),
      );
    });
    await act(async () => {
      await vi.advanceTimersByTimeAsync(100);
    });
    expect(updateBlock).toHaveBeenCalledExactlyOnceWith({
      uid: "block-uid",
      text: "A canvas block #claim",
    });
    expect(onTagAdded).toHaveBeenCalledExactlyOnceWith("A canvas block #claim");
  });
});

