88 "reports one outcome per node and progress after each" async () => { const sharedNodes = ["node-1", "node-2", "node-3", "node-4"].map(makeSharedNode); mockedMaterializeSharedNode .mockResolvedValueOnce(successResult(sharedNodes[0], "created")) .mockResolvedValueOnce(successResult(sharedNodes[1], "updated")) .mockResolvedValueOnce(successResult(sharedNodes[2], "skipped")) .mockResolvedValueOnce({ success: false, sourceModifiedAt: sharedNodes[3].lastModified, sourceNodeRid: sharedNodes[3].rid, error: { message: "title collision", stage: "title-collision" }, }); const onProgress = vi.fn(); const items = await importSharedNodes({ client, sharedNodes, discoveredNodes: [], onProgress, }); expect(items).toEqual([ { sharedNode: sharedNodes[0], status: "imported" }, { sharedNode: sharedNodes[1], status: "imported" }, { sharedNode: sharedNodes[2], status: "skipped" }, { sharedNode: sharedNodes[3], status: "failed", message: "title collision", }, ]); expect(items.filter(isFailedSharedNodeImport)).toEqual([items[3]]); expect(onProgress.mock.calls).toEqual([ [1, 4], [2, 4], [3, 4], [4, 4], ]); expect(mockedMaterializeSharedNode).toHaveBeenNthCalledWith(1, { client, sharedNode: sharedNodes[0], }); }
