300 "imports a discovered source this graph lacks before the node that names it" async () => { const source = { ...makeSharedNode("source"), rid: "orn:obsidian.note:vault-b/source", spaceUri: "obsidian:vault-b", }; const evidence = { ...makeSharedNode("evidence"), slots: { sourceDocument: source.rid }, }; const other = makeSharedNode("other"); mockedMaterializeSharedNode.mockImplementation(({ sharedNode }) => Promise.resolve(successResult(sharedNode, "created"))); const onProgress = vi.fn(); const items = await importSharedNodes({ client, sharedNodes: [evidence], discoveredNodes: [evidence, source, other], onProgress, }); expect(mockedFindImportedNodeUidBySourceRid).toHaveBeenCalledWith(source.rid); expect(mockedResolveSharedNodeTypes).toHaveBeenCalledWith({ client, sharedNodes: [evidence, source], }); expect(mockedMaterializeSharedNode.mock.calls.map(([args]) => args.sharedNode)).toEqual([source, evidence]); expect(items).toEqual([ { sharedNode: source, status: "imported" }, { sharedNode: evidence, status: "imported" }, ]); expect(onProgress.mock.calls).toEqual([ [1, 2], [2, 2], ]); }
