367 "does not add a source that is selected" async () => { const source = makeSharedNode("source"); const evidence = { ...makeSharedNode("evidence"), slots: { sourceDocument: source.sourceLocalId }, }; mockedMaterializeSharedNode.mockImplementation(({ sharedNode }) => Promise.resolve(successResult(sharedNode, "created"))); const items = await importSharedNodes({ client, sharedNodes: [evidence, source], discoveredNodes: [evidence, source], onProgress: vi.fn(), }); expect(mockedFindImportedNodeUidBySourceRid).not.toHaveBeenCalled(); expect(items.map((item) => item.sharedNode)).toEqual([source, evidence]); }
