409 "adds a source once when several nodes name it by a bare id" async () => { const source = makeSharedNode("source"); const first = { ...makeSharedNode("first"), slots: { sourceDocument: source.sourceLocalId }, }; const second = { ...makeSharedNode("second"), slots: { sourceDocument: source.sourceLocalId }, }; mockedMaterializeSharedNode.mockImplementation(({ sharedNode }) => Promise.resolve(successResult(sharedNode, "created"))); const items = await importSharedNodes({ client, sharedNodes: [first, second], discoveredNodes: [first, second, source], onProgress: vi.fn(), }); expect(mockedFindImportedNodeUidBySourceRid).toHaveBeenCalledTimes(1); expect(mockedFindImportedNodeUidBySourceRid).toHaveBeenCalledWith(source.rid); expect(items.map((item) => item.sharedNode)).toEqual([ source, first, second, ]); }
