{"chunk_id":"44cfec","wall_time_seconds":0.1427376,"exit_code":0,"original_token_count":4653,"output":"FILE apps/obsidian/src/utils/__tests__/schemaReconciliation.test.ts
8 "marks a database schema that the settings no longer have as stale" () => { const { staleSchemaIds } = diffSchemaIds({ databaseSchemaIds: ["old-source", "claim"], localSchemaIds: ["new-source", "claim"], }); expect([...staleSchemaIds]).toEqual(["old-source"]); }
16 "marks a settings schema that the database lacks as missing" () => { const { missingSchemaIds } = diffSchemaIds({ databaseSchemaIds: ["old-source", "claim"], localSchemaIds: ["new-source", "claim"], }); expect([...missingSchemaIds]).toEqual(["new-source"]); }
24 "finds nothing to do when the database matches the settings" () => { const { staleSchemaIds, missingSchemaIds } = diffSchemaIds({ databaseSchemaIds: ["claim", "supports"], localSchemaIds: ["supports", "claim"], }); expect(staleSchemaIds.size).toBe(0); expect(missingSchemaIds.size).toBe(0); }
37 "selects an item stored with no schema reference whose type is in the settings" () => { const ids = findIdsMissingSchema({ rows: [{ source_local_id: "n1", schema_id: null }], items: [{ id: "n1", typeId: "source" }], typeIds, }); expect([...ids]).toEqual(["n1"]); }
