  sourceLocalId: string;
  schemaId: number;
  spaceId: number;
  spaceName: string;
  spaceUri: string;
  platform: Platform;
  title: string;
  coreTitle?: string;
  created: string | null;
  lastModified: string;
  authorId?: number;
  directMetadata: Json;
  slots?: Record<string, string>;
};

export type SharedNodeRows = {
  nodes: SharedConcept[];
  directContents: SharedContent[];
  fullContentSummaries: SharedContentSummary[];
