  platform: Platform;
  title: string;
  coreTitle?: string;
  created: string | null;
  lastModified: string;
  authorId?: number;
  directMetadata: Json;
  slots?: Record<string, string>;
};

export type SharedNodeRows = {
  nodes: SharedConcept[];
  directContents: SharedContent[];
  fullContentSummaries: SharedContentSummary[];
  spaces: SharedSpace[];
};

const CONCEPT_COLUMNS_WITH_SLOTS =
  "core_title:literal_content->>core_title, is_schema, last_modified, schema_id, source_local_id, space_id, reference_content, concepts_of_relation(id, space_id, source_local_id)";
const DIRECT_CONTENT_COLUMNS =
  "author_id, created, last_modified, metadata, source_local_id, space_id, text, variant";
const FULL_CONTENT_SUMMARY_COLUMNS = "last_modified, source_local_id, space_id";
const SPACE_COLUMNS = "id, name, platform, url";

const getResourceKey = ({
  sourceLocalId,
  spaceId,
}: {
  sourceLocalId: string;
  spaceId: number;
}): string => `${spaceId}:${sourceLocalId}`;

const normalizeUtcTimestamp = (timestamp: string | null): string | null => {
  if (!timestamp) return null;
  const date = new Date(`${timestamp}Z`);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
};

const getLatestTimestamp = (timestamps: (string | null)[]): string | null => {
  const validTimestamps = timestamps
    .map(normalizeUtcTimestamp)
    .filter((timestamp): timestamp is string => typeof timestamp === "string");
  if (validTimestamps.length === 0) return null;
  return validTimestamps.reduce((latest, timestamp) =>
    timestamp > latest ? timestamp : latest,
  );
};

export const buildSharedNodes = ({
  nodes,
  directContents,
  fullContentSummaries,
  spaces,
}: SharedNodeRows): SharedNode[] => {
  const spacesById = new Map<number, ValidSharedSpace>(
    spaces.flatMap((space): [number, ValidSharedSpace][] => {
      if (
        typeof space.id !== "number" ||
        typeof space.name !== "string" ||
        space.platform === null ||
        typeof space.url !== "string"
      )
        return [];
      return [
        [
          space.id,
          {
            name: space.name,
            platform: space.platform,
            url: space.url,
          },
        ],
      ];
    }),
  );
  const directByResource = new Map<string, SharedContent>();
  directContents.forEach((content) => {
    if (
      typeof content.space_id !== "number" ||
      typeof content.source_local_id !== "string" ||
      content.variant !== "direct"
    )
      return;
    directByResource.set(
      getResourceKey({
        sourceLocalId: content.source_local_id,
        spaceId: content.space_id,
      }),
      content,
    );
  });

  const fullModifiedByResource = new Map<string, string | null>();
  fullContentSummaries.forEach((summary) => {
    if (
      typeof summary.space_id !== "number" ||
      typeof summary.source_local_id !== "string"
    )
      return;
    fullModifiedByResource.set(
      getResourceKey({
        sourceLocalId: summary.source_local_id,
        spaceId: summary.space_id,
      }),
      summary.last_modified,
    );
  });

  return nodes
    .flatMap((node): SharedNode[] => {
      if (
        node.is_schema !== false ||
        node.schema_id === null ||
        typeof node.space_id !== "number" ||
        typeof node.source_local_id !== "string"
      )
        return [];

      const resourceKey = getResourceKey({
        sourceLocalId: node.source_local_id,
        spaceId: node.space_id,
      });

      const space = spacesById.get(node.space_id);
      const direct = directByResource.get(resourceKey);
      if (!space || typeof direct?.text !== "string") return [];

      const created = normalizeUtcTimestamp(direct.created);
      const lastModified =
        getLatestTimestamp([
          node.last_modified,
          direct.last_modified,
          fullModifiedByResource.get(resourceKey) ?? null,
        ]) ?? created;
      if (!lastModified) return [];

      let rid: string;
      try {
        rid = spaceUriAndLocalIdToRid(space.url, node.source_local_id, "note");
      } catch {
        return [];
      }

      const nodeRidById = Object.fromEntries(
        node.concepts_of_relation
          .filter((c) => c.id !== null)
          .map((c) => {
            if (c.space_id === node.space_id) return [c.id, c.source_local_id];
            const space = spacesById.get(c.space_id || 0);
            if (!space || !c.source_local_id || !c.id) return [c.id, undefined];
            return [
              c.id,
              // To be reviewed if we have relations of relations
              spaceUriAndLocalIdToRid(space.url, c.source_local_id, "note"),
            ];
          }) as [number, string | undefined][],
      );
      const referenceContent = (node.reference_content ?? {}) as Record<
        string,
        number
      >;
      const slots = Object.fromEntries(
        Object.entries(referenceContent ?? {})
          .map(([k, v]) => [k, nodeRidById[v]])
          .filter(([, v]) => v !== undefined) as [string, string][],
      );

      return [
        {
          rid,
          sourceLocalId: node.source_local_id,
          schemaId: node.schema_id,
          spaceId: node.space_id,
          spaceName: space.name,
          spaceUri: space.url,
          platform: space.platform,
          title: direct.text,
          coreTitle: node.core_title ?? undefined,
          created,
          lastModified,
          authorId: direct.author_id ?? undefined,
          directMetadata: direct.metadata,
          slots: Object.keys(slots).length > 0 ? slots : undefined,
        },
      ];
    })
    .sort(
      (left, right) =>
        Date.parse(right.lastModified) - Date.parse(left.lastModified) ||
        left.title.localeCompare(right.title),
    );
};

const getAssociatedSpaces = async ({
  client,
  concepts,
  currentSpace,
  currentSpaceId,
}: {
  client: DGSupabaseClient;
  concepts: SharedConcept[];
  currentSpace?: SharedSpace;
  currentSpaceId?: number;
}): Promise<SharedSpace[]> => {
  const associatedSpaceIds = new Set(
    [
    `(<${URL_PATTERN}>|${URL_PATTERN})`, // a bare URL, rewritten only when a row matches it
  ].join("|"),
  "g",
);

/**
 * The forms of a locator that could match a recorded reference, in decreasing fidelity.
 * Two known mismatches: publication strips trailing punctuation that is inside the locator
 * here, and a markdown link percent-encodes what a vault path spells plainly (Obsidian
 * records `my folder/d.png` while the note holds `my%20folder/d.png`).
 */
export const lookupCandidates = (locator: string): string[] => {
  const candidates = [locator];
  const withoutPunctuation = locator.replace(TRAILING_PUNCTUATION, "");
  if (withoutPunctuation !== locator) candidates.push(withoutPunctuation);
  for (const candidate of [...candidates]) {
    try {
      const decoded = decodeURIComponent(candidate);
      if (decoded !== candidate) candidates.push(decoded);
    } catch {
      // A stray `%` is not an encoding, and the raw form is already a candidate.
    }
  }
  return candidates;
};

/**
 * What one match of `LINK_PATTERN` refers to, read from the capture groups in the order
 * the pattern lists its branches. Shared with `collectAssetLocators` so a caller sees
 * exactly the locators this file will rewrite.
 */
const parseMatch = (
  groups: (string | undefined)[],
):
  | {
      locator: string;
      form: ReferenceForm;
      declaredKind?: AssetKind;
      embedAlias?: string;
      linkText: string;
      /** Spelled as a markdown destination, so already percent-encoded. */
      isEncoded: boolean;
    }
  | undefined => {
  const [
    imageAlt,
    imageLocator,
    linkLabel,
    linkLocator,
    bracketedMediaKind,
    bracketedMediaLocator,
    mediaKind,
    mediaLocator,
    embedLocator,
    embedAlias,
    wikiLocator,
    wikiLabel,
    bareLocator,
  ] = groups;
  const bracketed =
    imageLocator ??
    linkLocator ??
    bracketedMediaLocator ??
    mediaLocator ??
    embedLocator ??
    wikiLocator ??
    bareLocator;
  if (bracketed === undefined) return undefined;
  const locator =
    bracketed.startsWith("<") && bracketed.endsWith(">")
      ? bracketed.slice(1, -1)
      : bracketed;

  const form: ReferenceForm =
    imageLocator !== undefined ||
    bracketedMediaLocator !== undefined ||
    mediaLocator !== undefined ||
    embedLocator !== undefined
      ? "embed"
      : bareLocator !== undefined
        ? "bare"
        : "link";

  return {
    locator,
    form,
    declaredKind: (bracketedMediaKind ?? mediaKind) as AssetKind | undefined,
    embedAlias,
    isEncoded:
      (imageLocator ?? linkLocator) !== undefined && locator === bracketed,
    // A wikilink embed carries no separate text, so its label comes from the asset.
    linkText: imageLocator ? (imageAlt ?? "") : (linkLabel ?? wikiLabel ?? ""),
  };
};

/**
 * Every locator this markdown refers an asset by, as `rewriteAssetLinks` reads them.
 * Widening these through `lookupCandidates` gives exactly the locators that would resolve,
 * so a caller deciding which references to act on cannot drift from the rewrite.
 */
export const collectAssetLocators = (markdown: string): string[] => {
  const locators: string[] = [];
  for (const match of markdown.matchAll(LINK_PATTERN)) {
    const [, ...groups] = match;
    const parsed = parseMatch(groups);
    if (parsed) locators.push(parsed.locator);
  }
  return locators;
};

export const rewriteAssetLinks = ({
  markdown,
  assets,
  unresolved = [],
}: {
  markdown: string;
  assets: ResolvedAsset[];
  unresolved?: UnresolvedAsset[];
}): string => {
  if (!assets.length && !unresolved.length) return markdown;
  const byLocator = new Map(
    assets.map((asset) => [asset.sourceLocator, asset]),
  );
  const unresolvedByLocator = new Map(
    unresolved.map((asset) => [asset.sourceLocator, asset]),
  );

  return markdown.replace(LINK_PATTERN, (match: string, ...args: unknown[]) => {
    const parsed = parseMatch(args as (string | undefined)[]);
    if (!parsed) return match;
    const { locator, form, declaredKind, embedAlias, linkText, isEncoded } =
      parsed;

    const context = { form, declaredKind, embedAlias };
    const candidates = lookupCandidates(locator);
    // A copy wins over a marker when two spellings match different rows.
    const matched =
      candidates.find((candidate) => byLocator.has(candidate)) ??
      candidates.find((candidate) => unresolvedByLocator.has(candidate));
    if (matched === undefined) return match;

    // Punctuation comes back only on a bare URL, where it was the sentence's. Inside
    // `![](…)` the locator is already delimited, so a trailing character belonged to
    // the URL and restoring it would leave a stray mark beside the embed.
    const trailing =
      form === "bare" && matched !== locator
        ? (locator.match(TRAILING_PUNCTUATION)?.[0] ?? "")
        : "";

    const asset = byLocator.get(matched);
    if (asset) return `${render({ asset, linkText, context })}${trailing}`;

    const unresolvedAsset = unresolvedByLocator.get(matched);
    if (!unresolvedAsset) return match;
    // A marked URL keeps its own text, so the sentence's punctuation is split off it
    // first. In an autolink it sits inside the brackets and stays there.
    const [reference, after] =
      trailing && match.endsWith(trailing)
        ? [match.slice(0, -trailing.length), trailing]
        : [match, ""];
    // The match offset is the only number `replace` passes.
    const offset = args.find((arg) => typeof arg === "number") as number;
    return `${renderMarked({
      marker: unresolvedAsset.marker,
      match: reference,
      // As spelled, not as recorded: the recorded form is decoded.
      locator,
      isEncoded,
      isInsideLinkLabel:
        match.startsWith("![") &&
        isInsideLinkLabel({
          markdown,
          start: offset,
          end: offset + match.length,
        }),
      linkText,
      embedAlias,
    })}${after}`;
  });
};
