import { addFile } from "@repo/database/lib/files";
import {
  MAX_ASSET_BYTES,
  isAssetTooLarge,
} from "@repo/database/lib/assetLimits";
import type { DGSupabaseClient } from "@repo/database/lib/client";
import { fetchAsset, fetchAssetDescriptor } from "./fetchRoamAsset";

/**
 * Copies one Roam asset into shared storage, recording it against the node that
 * references it.
 *
 * The markdown is never rewritten, so the URL that the page already holds is what lands
 * in `filepath` and is what a destination matches on. `addFile` hashes the bytes,
 * deduplicates through `file_exists`, and resolves a repeated reference, so this does
 * none of that itself.
 *
 * Reads each asset twice. `fetchRoamAsset` documents why neither read subsumes the other.
 */

export type CopiedAsset = {
  status: "copied";
  /** The URL as the markdown holds it. */
  sourceRef: string;
  /** SHA-256 of the stored bytes, as returned by `addFile`. */
  contentHash: string;
  /** The name Roam restored for the asset. */
  sourcePath: string;
};

export type SkippedAsset = {
  status: "skipped";
  sourceRef: string;
  /**
   * Undefined when the asset was declined before it was read: only `file.get` resolves a
   * name for an asset Roam recorded none for, and it is never called in that case.
   */
  sourcePath: string | undefined;
  reason: "too-large";
  size: number;
  limit: number;
};

export type AssetCopyResult = CopiedAsset | SkippedAsset;

export const copyAssetToSharedStorage = async ({
  client,
  spaceId,
  sourceLocalId,
  assetUrl,
  nodeCreated,
  nodeLastModified,
}: {
  client: DGSupabaseClient;
  spaceId: number;
  sourceLocalId: string;
  assetUrl: string;
  /** Used when Roam's storage reports no timestamps of its own. */
  nodeCreated: Date;
  nodeLastModified: Date;
}): Promise<AssetCopyResult> => {
  const descriptor = await fetchAssetDescriptor(assetUrl);
  const skip = ({
    size,
    sourcePath,
  }: {
    size: number;
    sourcePath: string | undefined;
  }): SkippedAsset => ({
    status: "skipped",
    sourceRef: assetUrl,
    sourcePath,
    reason: "too-large",
    size,
    limit: MAX_ASSET_BYTES,
  });

  // Decline an oversized asset from the descriptor alone, so its bytes never cross the
  // network. Not on an encrypted graph: there the descriptor measures the stored
  // ciphertext, which exceeds the file by an unknown factor, and the cap is about the
  // decrypted bytes that reach Supabase. Where the shortcut does not apply the check
  // simply moves after the download, which is what enforces the cap in every case.
  if (
    !window.roamAlphaAPI.graph.isEncrypted &&
    descriptor.size !== undefined &&
    isAssetTooLarge(descriptor.size)
  )
    return skip({ size: descriptor.size, sourcePath: descriptor.filename });

  const asset = await fetchAsset(assetUrl);
  if (isAssetTooLarge(asset.content.byteLength))
    return skip({
      size: asset.content.byteLength,
      sourcePath: asset.filename,
    });

  const contentHash = await addFile({
    client,
    spaceId,
    sourceLocalId,
    fname: assetUrl,
    sourcePath: asset.filename,
    mimetype: asset.mimetype,
    // Storage timestamps, not `File.lastModified`, which is the time of the call. The
    // node's own dates are the fallback, and are stable for the same reason.
    created: descriptor.createdAt ?? nodeCreated,
    lastModified: descriptor.modifiedAt ?? nodeLastModified,
    content: asset.content,
  });

  return {
    status: "copied",
    sourceRef: assetUrl,
    contentHash,
    sourcePath: asset.filename,
  };
};
import type { DGSupabaseClient } from "./client";
import { ridToSpaceUriAndLocalId, spaceUriAndLocalIdToRid } from "./rid";
import type { Enums, Json, Tables } from "../dbTypes";

type SharedConcept = Pick<
  Tables<"my_concepts">,
  | "is_schema"
  | "last_modified"
  | "schema_id"
  | "source_local_id"
  | "space_id"
  | "reference_content"
> & {
  core_title: string | null;
  concepts_of_relation: {
    id: number | null;
    space_id: number | null;
    source_local_id: string | null;
  }[];
};
type SharedContent = Pick<
  Tables<"my_contents">,
  | "author_id"
  | "created"
  | "last_modified"
  | "metadata"
  | "source_local_id"
  | "space_id"
  | "text"
  | "variant"
>;
type SharedContentSummary = Pick<
  Tables<"my_contents">,
  "last_modified" | "source_local_id" | "space_id"
>;
type SharedSpace = Pick<
  Tables<"my_spaces">,
  "id" | "name" | "platform" | "url"
>;
type Platform = Enums<"Platform">;

type ValidSharedSpace = {
  name: string;
  platform: Platform;
  url: string;
};

export type SharedNode = {
  rid: string;
  sourceLocalId: string;
  schemaId: number;
  spaceId: number;
  spaceName: string;
  spaceUri: string;
  platform: Platform;
  title: string;
  coreTitle?: string;
  created: string | null;
  lastModified: string;
  authorId?: number;
  directMetadata: Json;
  slots?: Record<string, string>;
};

export type SharedNodeRows = {
  nodes: SharedConcept[];
  directContents: SharedContent[];
  fullContentSummaries: SharedContentSummary[];
  spaces: SharedSpace[];
};

const CONCEPT_COLUMNS_WITH_SLOTS =
  "core_title:literal_content->>core_title, is_schema, last_modified, schema_id, source_local_id, space_id, reference_content, concepts_of_relation(id, space_id, source_local_id)";
const DIRECT_CONTENT_COLUMNS =
  "author_id, created, last_modified, metadata, source_local_id, space_id, text, variant";
const FULL_CONTENT_SUMMARY_COLUMNS = "last_modified, source_local_id, space_id";
const SPACE_COLUMNS = "id, name, platform, url";

const getResourceKey = ({
  sourceLocalId,
  spaceId,
}: {
  sourceLocalId: string;
  spaceId: number;
}): string => `${spaceId}:${sourceLocalId}`;

const normalizeUtcTimestamp = (timestamp: string | null): string | null => {
  if (!timestamp) return null;
  const date = new Date(`${timestamp}Z`);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
};

const getLatestTimestamp = (timestamps: (string | null)[]): string | null => {
  const validTimestamps = timestamps
    .map(normalizeUtcTimestamp)
    .filter((timestamp): timestamp is string => typeof timestamp === "string");
  if (validTimestamps.length === 0) return null;
  return validTimestamps.reduce((latest, timestamp) =>
    timestamp > latest ? timestamp : latest,
  );
};

export const buildSharedNodes = ({
  nodes,
  directContents,
  fullContentSummaries,
  spaces,
}: SharedNodeRows): SharedNode[] => {
  const spacesById = new Map<number, ValidSharedSpace>(
    spaces.flatMap((space): [number, ValidSharedSpace][] => {
      if (
        typeof space.id !== "number" ||
        typeof space.name !== "string" ||
        space.platform === null ||
        typeof space.url !== "string"
      )
        return [];
      return [
        [
          space.id,
          {
            name: space.name,
            platform: space.platform,
            url: space.url,
          },
        ],
      ];
    }),
  );
  const directByResource = new Map<string, SharedContent>();
  directContents.forEach((content) => {
    if (
      typeof content.space_id !== "number" ||
      typeof content.source_local_id !== "string" ||
      content.variant !== "direct"
    )
      return;
    directByResource.set(
      getResourceKey({
        sourceLocalId: content.source_local_id,
        spaceId: content.space_id,
      }),
      content,
    );
  });

  const fullModifiedByResource = new Map<string, string | null>();
  fullContentSummaries.forEach((summary) => {
    if (
      typeof summary.space_id !== "number" ||
      typeof summary.source_local_id !== "string"
    )
      return;
    fullModifiedByResource.set(
      getResourceKey({
        sourceLocalId: summary.source_local_id,
