    imageAlt,
    imageLocator,
    linkLabel,
    linkLocator,
    bracketedMediaKind,
    bracketedMediaLocator,
    mediaKind,
    mediaLocator,
    embedLocator,
    embedAlias,
    wikiLocator,
    wikiLabel,
    bareLocator,
  ] = groups;
  const bracketed =
    imageLocator ??
    linkLocator ??
    bracketedMediaLocator ??
    mediaLocator ??
    embedLocator ??
    wikiLocator ??
    bareLocator;
