    return skip({ size: descriptor.size, sourcePath: descriptor.filename });

  const asset = await fetchAsset(assetUrl);
  if (isAssetTooLarge(asset.content.byteLength))
    return skip({
      size: asset.content.byteLength,
      sourcePath: asset.filename,
    });

